// Types of the data generated by tools/pack.py in source/gen/assets.c.
#pragma once
#include "common.h"

typedef struct { const char *name; u8 page; u16 x, y, w, h; s16 rx, ry; } PeopleSprite;
/** Classic interface graphic (client/public/classic), sorted by name. */
typedef PeopleSprite UiSprite;
/** `page`: furniture page belonging to its definition. */
typedef struct { u8 page; u16 x, y, w, h; s16 ox, oy; float depth; u8 alpha; u8 flags; } FurniPart;
enum { PART_SHADOW = 1, PART_ADD = 2 };
typedef struct { u16 def; u8 rot, state; u16 frame, count; const FurniPart *parts; } FurniVariant;
/** `tex`: has its own texture in romfs:/furni/d<id>.t3x; `icon_*`: catalogue icon inside it. */
typedef struct { u16 id; u8 kind, w, h; u16 seat; u8 states, flags, rotations, drink; const char *name; u8 tex; u16 icon_x, icon_y, icon_w, icon_h; const char *drinks, *desc; u8 icon_page, casino; u32 chips; } FurniDef;
typedef struct { u16 def; u8 page; u32 bytes; } FurniTexture;
extern const FurniTexture furni_textures[];
extern const int furni_texture_count;
typedef struct { u16 def, state, tick, period; const u16 *frames; } FurniAnimation;
extern const FurniAnimation furni_animations[];
extern const int furni_animation_count;
typedef struct { u8 id; const char *name; } DrinkName;
typedef struct { const char *name; u8 breeds, color_count; u32 colors[40]; } PetKind;
typedef struct { const char *id, *name, *layout, *body; } CatPage;
/** `pages`: comma-separated page ids with commas at both ends (",3,5,"). */
typedef struct { u16 id, def; u16 amount; u8 available; u32 price; const char *name, *desc, *pages; } CatOffer;
enum { DEF_SIT = 1, DEF_LAY = 2, DEF_STACK = 4, DEF_TELEPORTER = 8, DEF_GATE = 16, DEF_SOLID = 32, DEF_REDEEM = 64, DEF_HOLO = 128 };
enum { KIND_BLOCK, KIND_SIT, KIND_FLOOR, KIND_TOGGLE, KIND_DICE, KIND_WALL };
typedef struct { const char *label, *parts; char sex; const char *layers; } WardrobeEntry;
typedef struct { u8 index; const char *part; u8 n; const char *act[16]; s8 frm[16], offx[16], offy[16], offd[16]; } DanceTrack;
typedef struct { u8 drink; const char *model; } DrinkModel;
typedef struct { const char *file; u16 x, y, w, h; } RoomTile;
typedef struct { const char *model, *file; s16 x, y; u16 w, h; u8 door_x, door_y; const char *rows; u8 tile_count; const RoomTile *tiles; } RoomBackground;
typedef struct { u8 kind; const char *id; u32 color; const char *texture; u16 w, h; } FinishChoice;
extern const FinishChoice finish_choices[];
extern const int finish_choice_count, finish_price;
/** Public room layer: region (page,sx,sy,w,h) drawn at (x,y) with size (dw,dh). */
/** `role`: 0 always, 1 under the floor (drawn first), 10 + 2k / 11 + 2k open / closed picture of
 *  switch k (booth curtains 1 and 2, the lift door), chosen by source/pool.c. */
typedef struct { u8 page; u16 sx, sy, w, h; s16 x, y; u16 dw, dh; float depth; u8 alpha, frames, frame, background, role; } SceneSprite;
/** Classic activity artwork packed in the scene pages: registration (rx, ry) like the web atlas. */
typedef struct { const char *name; u8 page; u16 sx, sy, w, h; s16 rx, ry; } SceneArt;
/** Layered public room (romfs:/gfx/scene_<model>_<page>.t3x). `water`: water height or -1. */
typedef struct { const char *model; u8 pages; int count; const SceneSprite *sprites; s8 water; int art_count; const SceneArt *art; } Scene;
typedef struct { u32 id; u16 def; u8 x, y, rot; u16 z; } RoomItem;
typedef struct {
  const char *key, *name, *classic, *rows;
  u8 door_x, door_y, dir, target_x, target_y;
  u16 item_count; const RoomItem *items;
} RoomModel;

extern const int atlas_page_count;
/** Pages from this index on (character skins) are loaded on demand by gfx.c. */
extern const int atlas_page_resident;
/** Name of each page (atlasN in RGBA8, atlasgN in LA8). */
extern const char *const atlas_page_files[];
extern const PeopleSprite people_sprites[];
extern const int people_sprite_count;
extern const UiSprite ui_sprites[];
extern const int ui_sprite_count;
extern const FurniVariant furni_variants[];
extern const int furni_variant_count;
extern const FurniDef furni_defs[];
/** Definitions of the jukeboxes and Trax machines (room playlist, source/music.c). */
extern const u16 music_machines[];
extern const int music_machine_count;
extern const int furni_def_count;
extern const CatPage cat_pages[];
extern const int cat_page_count;
extern const CatOffer cat_offers[];
extern const int cat_offer_count;
extern const WardrobeEntry wardrobe_hair[], wardrobe_tops[], wardrobe_bottoms[], wardrobe_shoes[], wardrobe_faces[];
extern const int wardrobe_hair_count, wardrobe_tops_count, wardrobe_bottoms_count, wardrobe_shoes_count, wardrobe_faces_count;
extern const DanceTrack dance_tracks[];
extern const int dance_track_count;
typedef struct { const char *name; u16 x, y, w, h; s16 rx, ry; } PetPart;
typedef struct { const char *from, *to; u8 flip; } PetAlias;
typedef struct { const char *key; s8 x[5], y[5]; } PetOffset;
extern const PetPart pet_parts[];
extern const int pet_part_count;
extern const PetAlias pet_aliases[];
extern const int pet_alias_count;
extern const PetOffset pet_offsets[];
extern const int pet_offset_count;
extern const char *const pet_palettes[];
extern const int pet_palette_count;
extern const char *const pet_kind_keys[];
extern const int pet_price;
extern const PetKind pet_kinds[];
extern const int pet_kind_count;
extern const DrinkName drink_names[];
extern const int drink_name_count;
extern const DrinkModel drink_models[];
extern const int drink_model_count;
extern const RoomBackground room_backgrounds[];
extern const int room_background_count;
extern const Scene scenes[];
extern const int scene_count;
extern const PeopleSprite swim_sprites[];
extern const int swim_sprite_count;
extern const RoomModel room_models[];
extern const int room_model_count;

typedef struct { u8 size; u16 code, x, y, w, h; s8 left, top, advance; } FontGlyph;
extern const FontGlyph font_glyphs[];
extern const int font_glyph_count;
